    return {
      kind: "member",
      id: member[1],
      view: member[2] ? "history" : "summary",
    };
  const funder = /^\/funders\/([^/]+)(?:\/(history))?\/?$/u.exec(path);
  if (funder && funderIdPattern.test(funder[1]))
    return {
      kind: "funder",
      id: funder[1],
      view: funder[2] ? "history" : "summary",
    };
  return { kind: "invalid" };
}

