//! Stored profiles, declaration occurrences, and exact currency summaries.

use std::str::FromStr;

use bigdecimal::BigDecimal;
use thiserror::Error;

use crate::domain::repositories::entity_details::EntityDetailsRepoError;
use chrono::{DateTime, Utc};

use super::{
    funder::{Funder, FunderId},
    parliament_member::{MemberId, MemberIdError},
};

/// Entity detail lookup failure.
#[derive(Debug, Error)]
pub enum EntityDetailsError {
    /// Member identity could not be parsed.
    #[error("Invalid MP ID")]
    InvalidMemberId(#[source] MemberIdError),
    /// Funder identity could not be parsed.
    #[error("Invalid funder ID")]
    InvalidFunderId(#[source] uuid::Error),
    /// No stored identity matches the request.
    #[error("entity not found")]
    NotFound,
    /// Private database diagnostics.
    #[error(transparent)]
    Unexpected(#[from] EntityDetailsRepoError),
}

/// Parsed member detail lookup.
#[derive(Clone, Copy, Debug)]
pub struct MemberDetailsRequest {
    id: MemberId,
}

impl MemberDetailsRequest {
    /// Parliament identity to look up.
    #[must_use]
    pub const fn id(self) -> MemberId {
        self.id
    }
}

impl FromStr for MemberDetailsRequest {
    type Err = EntityDetailsError;

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        value
            .parse()
            .map(|id| Self { id })
            .map_err(EntityDetailsError::InvalidMemberId)
    }
}

/// Parsed funder detail lookup.
#[derive(Clone, Copy, Debug)]
pub struct FunderDetailsRequest {
    id: FunderId,
}

impl FunderDetailsRequest {
    /// Persistent funder identity to look up.
    #[must_use]
    pub const fn id(self) -> FunderId {
        self.id
    }
}

impl FromStr for FunderDetailsRequest {
    type Err = EntityDetailsError;

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        value
            .parse()
            .map(|id| Self { id })
            .map_err(EntityDetailsError::InvalidFunderId)
    }
}

/// Latest stored member profile, not membership at the time of a payment.
#[derive(Clone, Debug)]
pub struct MemberProfile {
    /// Parliament identity.
    pub id: MemberId,
    /// Source name.
    pub name: String,
    /// Latest recorded party identity.
    pub party_id: i32,
    /// Latest recorded party name.
    pub party_name: String,
    /// Latest membership description, including constituencies and Lords memberships.
    pub membership_from: String,
    /// Current Commons membership.
    pub is_current_commons: bool,
}

/// A named funder on a declaration.
import { redirect } from "@sveltejs/kit";
import { readDetailRoute } from "../../lib/entity-details";
import { searchConfiguration } from "../../lib/search";
import { loadDetails } from "../../lib/server/entity-details";
import { searchEntities } from "../../lib/server/search";
import type { PageModel } from "../../lib/page";
import type { PageServerLoad } from "./$types";
export const load = (async ({ url, fetch, request, depends }) => {
  if (url.searchParams.has("strictness")) {
    const canonical = new URL(url);
    canonical.searchParams.delete("strictness");
    if (canonical.pathname === "/") canonical.pathname = "/search";
    redirect(308, canonical.pathname + canonical.search);
  }
  depends("exposed:page");
  if (url.pathname === "/") {
    if (url.searchParams.has("q")) redirect(307, `/search${url.search}`);
    return { model: { kind: "landing" } satisfies PageModel };
  }
  if (url.pathname === "/methodology")
    return { model: { kind: "methodology" } satisfies PageModel };
  const route = readDetailRoute(url.pathname);
  const origin = (
    process.env.EXPOSED_API_ORIGIN || "http://127.0.0.1:6999"
  ).replace(/\/$/, "");
  let model: PageModel;
  if (route.kind !== "search") {
    model = {
      kind: "detail",
      route,
      result:
        route.kind === "invalid"
          ? { kind: "not-found" }
          : await loadDetails(route, request.signal, fetch, origin),
    };
  } else {
    const query = url.searchParams.get("q") ?? "";
    const term = query.trim();
    model = { kind: "search", query, result: { status: "idle" } };
    if ([...term].length >= searchConfiguration.minimumCharacters) {
      try {
        model.result = {
          status: "success",
          term,
          entities: await searchEntities(term, request.signal, fetch, origin),
        };
      } catch (error) {
        model.result = {
          status: "error",
          term,
          message:
            error instanceof Error
              ? error.message
              : "Search couldn’t load. Try again.",
        };
      }
    }
  }
  return { model };
}) satisfies PageServerLoad;
